function brief(){let blocked=state.cases.filter(c=>assessment(c).status==='BLOCKED').length;return `<section class="hero">${banner('Demilitarization pathways grounded in civilian protection and independent verification','An independent public-interest workspace connecting international law, reciprocal restraint, nuclear safety, humane reintegration, transparent reconstruction and expert-reviewed policy scenarios. It cannot negotiate or implement a settlement.','RUSSIA–UKRAINE · INDEPENDENT WORKBENCH')}<div class="actions"><a href="#/workbench" class="btn primary">Open negotiation workbench</a><a href="#/demilitarization" class="btn">Compare demilitarization pathways</a><a href="#/forge" class="btn">Open Pathway Forge</a><a href="#/review" class="btn">Prepare expert review</a><a href="#/constraints" class="btn">Examine hard constraints</a><a href="#/evidence" class="btn">Review evidence provenance</a><a href="#/legal" class="btn">Official legal documentation</a></div><div class="notice critical"><b>Research baseline — not live:</b> October 2026 reporting documents incompatible public positions and continuing civilian harm. No ceasefire, guarantor commitment, OSCE deployment or official endorsement is assumed. Every proposed action requires independent verification.</div></section>
<div class="grid tight"><div class="card"><div class="stat">${ISSUES.length}</div><div class="label">Issue templates; not agreed terms</div></div><div class="card"><div class="stat">${ACTORS.length}</div><div class="label">Potential stakeholders; participation unverified</div></div><div class="card"><div class="stat">${state.cases.length}</div><div class="label">Local research cases</div></div><div class="card"><div class="stat">${blocked}</div><div class="label">Cases with explicit blockers</div></div></div>
<h2>Three distinct, non-substitutable layers</h2><div class="grid"><div class="card"><span class="kicker">01 · Immediate protection</span><h3>Humanitarian arrangements</h3><p>Prisoner and child reunification mechanisms, aid access, nuclear safety and limited civilian protection measures. Narrow deals may be possible without a comprehensive settlement, but still need safe access and party consent.</p><button class="btn sm" data-act="example" data-issue="prisoner-exchanges">Examine prisoner exchanges</button></div><div class="card"><span class="kicker">02 · Cessation of hostilities</span><h3>Mutual military restraint and credible observation</h3><p>Defined scope, bilateral authority, synchronized acceptance, reporting, incident investigation, monitoring security, non-compliance consequences and escalation safeguards.</p><button class="btn sm" data-act="example" data-issue="energy-truce">Examine energy restraint</button></div><div class="card"><span class="kicker">03 · Durable political and economic terms</span><h3>Security, law and reconstruction</h3><p>Sovereignty, enforceable security arrangements, sanctions law, financing, justice, return rights and reconstruction governance each have distinct institutional owners and legal veto points.</p><button class="btn sm" data-act="example" data-issue="security-guarantees">Examine security guarantees</button></div></div>
<h2>What changed from v1.1?</h2><div class="two"><div class="card"><h3>Removed</h3><p>XP, completion badges, rankings, randomized diplomatic pairings, simulated likelihood scores, progress HUD, and a fictional ladder from learning to peace.</p></div><div class="card"><h3>Added</h3><p>Prerequisite gates, documented positions, veto actors, consent checkpoints, noncompliance protocols, evidence-linked claims, adversarial review, audit trail and exportable briefing memos.</p></div></div><h2>Current reference signals</h2><div class="grid">${['ohchr-sep','reuters-ceasefire-2026','reuters-energy-2026','reuters-aid-2026'].map(k=>{let s=SOURCES.find(x=>x.id===k);return s?`<article class="card"><span class="kicker">${esc(s.date)} · ${esc(s.class)}</span><h3>${esc(s.name)}</h3><p>${esc(s.claim)}</p>${link(s.url,'Read primary or cited reporting')}</article>`:''}).join('')}</div>`}
function constraints(){return banner('Diplomatic constraints & veto map','A non-exhaustive analytical model of actors, recognition, negotiating sequence, command authority, legal obligations and implementation constraints. Positions are dated; classified intentions and bargaining ranges are unknown.','REAL-WORLD NEGOTIATION MECHANICS')+`<div class="notice warning"><b>Model discipline:</b> Actor capability is not willingness. A public statement is not a signed agreement. A signed text is not compliance. A monitor is not an enforcer. An analytical seat is not authority.</div><div class="grid">${TENSIONS.map(([h,t])=>`<article class="card"><h3>${esc(h)}</h3><p>${esc(t)}</p></article>`).join('')}</div><h2>Consent and decision rights</h2><div class="tablewrap"><table><thead><tr><th>Actor type</th><th>Can decide</th><th>Cannot be assumed to decide</th></tr></thead><tbody><tr><td>Ukraine's competent authorities</td><td>Ukrainian security, territorial and legal commitments within their authority</td><td>Russian actions; international actors' funding or defense commitments</td></tr><tr><td>Russia's competent authorities</td><td>Russian restraint, withdrawal and Russian commitments within their authority</td><td>Ukrainian sovereignty or consent; third-state legal recognition</td></tr><tr><td>Facilitators / intermediaries</td><td>Whether to facilitate, within their own mandates and the parties' consent</td><td>Bind belligerents to cease fire</td></tr><tr><td>Guarantors, NATO / EU actors</td><td>Commitments through their separate domestic or organizational processes</td><td>Be volunteered as guarantors by a third party's plan</td></tr><tr><td>Verification organizations</td><td>Observe/report if a new mandate, resources and safe access exist</td><td>Compel compliance without explicit authority</td></tr><tr><td>Local communities / humanitarian bodies</td><td>Needs identification, safeguards and legitimate local delivery within their remit</td><td>Sign a sovereign interstate settlement</td></tr></tbody></table></div>
<h2>Strategic and political feasibility screen</h2><div class="tablewrap"><table><thead><tr><th>Decision variable</th><th>Evidence needed (safe, aggregate)</th><th>Failure of analysis</th></tr></thead><tbody><tr><td>War continuation incentives</td><td>Dated public objectives, sustainability assessments from multiple independent sources, competing narratives and uncertainty</td><td>Assuming a peace dividend automatically beats perceived military alternatives</td></tr><tr><td>Domestic authority and legitimacy</td><td>Constitutional competences, legislative approvals, political constraints and public positions</td><td>Confusing a leader's speech with binding national consent</td></tr><tr><td>External leverage and veto players</td><td>Funding, guarantee, sanctions and alliance decision rights, with explicit ratification dependencies</td><td>Offering concessions controlled by unrelated institutions</td></tr><tr><td>Military de-escalation credibility</td><td>Public top-level agreed prohibitions, start/stop rules, responsible authorities, safe monitoring and independent reports</td><td>Assuming command compliance or frictionless verification</td></tr><tr><td>Bargaining sequence</td><td>Possible limited humanitarian steps, partial restraint, monitored armistice and sovereign settlement—each with its own consent conditions</td><td>Conflating a sectoral announcement with a comprehensive peace agreement</td></tr><tr><td>Sanctions and recovery incentives</td><td>Relevant statutes, lawfully reversible measures, independent audited delivery and governance</td><td>Inventing sanction-relief powers or unenforceable reconstruction promises</td></tr></tbody></table></div><h2>Dated public-position anchors</h2><div class="grid">${['uk-e3-jun','paris-2026','reuters-ceasefire-2026','reuters-zone-2026'].map(k=>{let s=SOURCES.find(x=>x.id===k);return s?`<div class="card"><span class="kicker">${esc(s.date)} · ${esc(s.class)}</span><h3>${esc(s.name)}</h3><p>${esc(s.claim)}</p>${link(s.url,'Check original context')}</div>`:''}).join('')}</div><div class="notice critical"><b>Active contradictions are not balanced away by a scoring system.</b> The position of any party may change; evaluate proposals from multiple dated sources and document irreconcilable requirements before asking whether a mediator can deliver them.</div><h2>Five non-negotiable evaluation questions</h2><ol><li>Which empowered body must agree and how is its explicit agreement recorded?</li><li>What specific action changes and which mutually incompatible positions obstruct it?</li><li>What evidence distinguishes a promise from behavior, who may inspect, and what happens when access fails?</li><li>Who pays, secures, delivers and maintains the arrangement, and what happens when enforcement is contested?</li><li>What does a failed or manipulated agreement do to civilians, sovereignty and future bargaining incentives?</li></ol><div class="actions"><a href="#/workbench" class="btn primary">Apply these checks to a case</a></div>`}
function stakeholderDetails(a){let m=a.stakeholderModel||{};return `<article class="card profile-scroll" tabindex="0" aria-label="Independently scrollable stakeholder dossier"><span class="kicker">${esc(a.kind||'candidate actor')} · CAPABILITY MODEL</span><h2>${esc(a.name)}</h2>${chip('Engagement not verified','warn')}<p><b>Authority / remit model:</b> ${esc(a.mandate)}</p><p><b>Constraints:</b> ${esc(a.constraint)}</p><p><b>Potential capabilities:</b> ${(a.capabilities||[]).map(x=>chip(x)).join('')}</p><hr class="divider"><h3>What is and is not established</h3><p>${esc(m.inferredIncentive||'Potential incentive unknown')}</p><p><b>Red lines:</b> ${esc(m.redLines||'Unverified')}</p><p><b>Alternative to an agreement (BATNA):</b> ${esc(m.BATNA||'Unverified')}</p><p><b>Failure / spoiler considerations:</b> ${esc(m.spoilerRisk||'Requires research')}</p><div class="notice warning">This profile is a research hypothesis. It is not an official statement of willingness or authorization. Validate with attributable, dated sources.</div><div class="actions"><button class="btn primary" data-act="case-actor" data-id="${esc(a.id)}">Add as proposed stakeholder</button><a href="#/evidence" class="btn">Source register</a></div>${financeForActor(a.id)}<h3>Verification prompts</h3><p>What legal instrument grants competence? Is there a dated public position, a negotiable range, and a named authorized representative? What evidence would falsify our assumption?</p></article>`}
