async function importFile(file){if(!file)return;if(file.size>6*1024*1024){showToast('File too large (>6 MB).');return}try{let raw=JSON.parse(await file.text()),w=raw.schema===1?importLegacy(raw):raw.version===2?importV2ResearchBackup(raw):normalize(raw);if(!confirm('Replace the current local workspace with this imported file? Export your existing data first.'))return;state=w;ui.caseId=state.cases[0]?.id||null;ui.forge.problem=trim(state.prefs.forgeProblem,4000);save();render();showToast('Imported as unverified local research drafts.')}catch(e){showToast('Import rejected: '+e.message)}}
